insert into public.formula_cards (
  id, chapter_id, title, card_type, body, formulas, variables, conditions, table_data, diagram_data, diagram_svg, recall_data, importance, source_page, sort_order, is_active
)
values
  ('neet-biology-reproduction-in-organisms-lifespan-and-reproduction', 'neet-biology-reproduction-in-organisms', 'Lifespan and Reproduction', 'concept', 'Lifespan is the period from birth to natural death. Reproduction produces young ones similar to the organism.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed recall"],"rows":[["Lifespan","Period from birth to natural death"],["Reproduction","Production of young ones similar to itself"],["Unicellular organisms","No natural death; the source notes they are an exception to individual immortality"]]}'::jsonb, null, null, '{"recall_question":"What is lifespan?","reveal_answer":"The period from birth to natural death.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 90, 1, true),
  ('neet-biology-reproduction-in-organisms-lifespan-examples', 'neet-biology-reproduction-in-organisms', 'Lifespan Examples', 'fact', 'The source gives exact lifespan examples for plants and animals.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Organism","Lifespan"],"rows":[["Rose","5-7 years"],["Rice plant","3-7 months"],["Banyan tree","400+ yrs"],["Banana tree","2-3 yrs"],["Dog","22 yrs"],["Butterfly","1-2 weeks"],["Fruit fly","2 weeks"],["Parrot","140 yrs"],["Crocodile","60 yrs"],["Horse","40-50 yrs"],["Tortoise","100-150 yrs"],["Elephant","50-70 yrs"]]}'::jsonb, null, null, '{"recall_question":"Which listed organism has a 400+ year lifespan?","reveal_answer":"Banyan tree.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 90, 2, true),
  ('neet-biology-reproduction-in-organisms-asexual-reproduction', 'neet-biology-reproduction-in-organisms', 'Asexual Reproduction', 'concept', 'Asexual reproduction is production of offspring by a single parent.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Source-backed detail"],"rows":[["Parent","Single parent"],["Typical organisms","Unicellular organisms, simple plants and simple animals"],["Offspring","Identical to one another and to the parent"],["Clone","Morphologically and genetically similar individuals"]]}'::jsonb, null, null, '{"recall_question":"What is a clone in this chapter?","reveal_answer":"Morphologically and genetically similar individuals.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 90, 3, true),
  ('neet-biology-reproduction-in-organisms-binary-vs-multiple-fission', 'neet-biology-reproduction-in-organisms', 'Binary vs Multiple Fission', 'comparison', 'Fission is division of the parent cell into two or more individuals.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Type","Recall","Examples"],"rows":[["Binary fission","Parent divides into two individuals","Amoeba, Paramecium"],["Multiple fission","Parent divides into many individuals","Plasmodium, Amoeba"]]}'::jsonb, null, null, '{"recall_question":"Which fission type forms many individuals from one parent?","reveal_answer":"Multiple fission.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 90, 4, true),
  ('neet-biology-reproduction-in-organisms-amoeba-encystation', 'neet-biology-reproduction-in-organisms', 'Amoeba Encystation and Sporulation', 'sequence', 'Amoeba forms a cyst in unfavourable conditions and releases pseudopodiospores under favourable conditions.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Source-backed event"],"rows":[["1","Amoeba withdraws pseudopodia under unfavourable conditions"],["2","It secretes a three-layered hard covering or cyst"],["3","On return of favourable conditions, multiple fission occurs inside the cyst"],["4","Many minute amoebae or pseudopodiospores are formed"],["5","Cyst wall bursts and spores are liberated"]]}'::jsonb, null, null, '{"recall_question":"What are formed inside the Amoeba cyst during favourable conditions?","reveal_answer":"Many minute amoebae or pseudopodiospores.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 90, 5, true),
  ('neet-biology-reproduction-in-organisms-budding-fragmentation', 'neet-biology-reproduction-in-organisms', 'Budding and Fragmentation', 'comparison', 'Budding forms a new individual from a bud; fragmentation forms adults from body fragments.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Method","Source-backed recall","Examples"],"rows":[["Budding","Bud appears and grows on the parent, then detaches after maturation","Hydra, Sponge, Yeast"],["Fragmentation","Parent body breaks into fragments, each fragment grows into an adult","Hydra"]]}'::jsonb, null, null, '{"recall_question":"Which asexual method uses a bud that detaches after maturation?","reveal_answer":"Budding.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 90, 6, true),
  ('neet-biology-reproduction-in-organisms-vegetative-propagation-examples', 'neet-biology-reproduction-in-organisms', 'Vegetative Propagules', 'examples', 'Vegetative propagation forms offspring from vegetative propagules in plants.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Propagule","Exact source example"],"rows":[["Buds or eyes","Potato tuber"],["Rhizome","Banana and ginger"],["Adventitious buds","Bryophyllum leaf margins"],["Bulbil","Agave"],["Offset","Water hyacinth"],["Other listed propagules","Runner, sucker, tuber, bulb etc."]]}'::jsonb, null, null, '{"recall_question":"Which plant has adventitious buds on leaf margins?","reveal_answer":"Bryophyllum.","key_points":[],"examples":["Potato tuber, banana, ginger, Agave, water hyacinth"],"neet_traps":[]}'::jsonb, 5, 90, 7, true),
  ('neet-biology-reproduction-in-organisms-asexual-structures', 'neet-biology-reproduction-in-organisms', 'Asexual Reproductive Structures', 'examples', 'The source names specialized asexual structures across groups.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Structure","Source-backed example/detail"],"rows":[["Zoospores","Microscopic motile structures in some algae and protists"],["Conidia","Penicillium"],["Gemmules","Sponge"],["Asexual reproduction","Common in algae and fungi; during adverse conditions they shift to sexual reproduction"]]}'::jsonb, null, null, '{"recall_question":"Which asexual structure is listed for Penicillium?","reveal_answer":"Conidia.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 91, 8, true),
  ('neet-biology-reproduction-in-organisms-asexual-vs-sexual', 'neet-biology-reproduction-in-organisms', 'Asexual vs Sexual Reproduction', 'comparison', 'Sexual reproduction is elaborate, complex and slow compared with asexual reproduction.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Asexual reproduction","Sexual reproduction"],"rows":[["Parent/gametes","Single parent; no male and female gamete fusion","Male and female gametes from same or different individuals"],["Offspring","Identical to parent and each other","Not identical to parents or among themselves"],["Speed/complexity","Simple and common in simple organisms","Elaborate, complex and slow"]]}'::jsonb, null, null, '{"recall_question":"Which reproduction type produces non-identical offspring?","reveal_answer":"Sexual reproduction.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 91, 9, true),
  ('neet-biology-reproduction-in-organisms-life-phases', 'neet-biology-reproduction-in-organisms', 'Juvenile, Reproductive and Senescent Phases', 'classification', 'Organisms pass through phase changes before, during and after reproductive maturity.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Phase","Source-backed recall"],"rows":[["Juvenile phase","Period of growth before reproductive maturity"],["Vegetative phase","Juvenile phase in plants"],["Reproductive phase","Flowering indicates beginning of reproductive phase in higher plants"],["Senescence","End of reproductive phase with body changes such as slowing metabolism, ultimately leading to death"]]}'::jsonb, null, null, '{"recall_question":"What is the juvenile phase called in plants?","reveal_answer":"Vegetative phase.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 91, 10, true),
  ('neet-biology-reproduction-in-organisms-unusual-flowering-and-breeders', 'neet-biology-reproduction-in-organisms', 'Unusual Flowering and Breeder Types', 'fact', 'The source highlights unusual flowering periodicity and breeding patterns.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Bamboo species","Flower only once in their lifetime after 50-100 years, produce many fruits and die"],["Strobilanthus kunthiana","Flowers once in 12 years"],["Seasonal breeders","Reproductive cycles only during favourable seasons"],["Continuous breeders","Reproductively active throughout reproductive phase"]]}'::jsonb, null, null, '{"recall_question":"Which listed plant flowers once in 12 years?","reveal_answer":"Strobilanthus kunthiana.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 91, 11, true),
  ('neet-biology-reproduction-in-organisms-oestrus-vs-menstrual', 'neet-biology-reproduction-in-organisms', 'Oestrus vs Menstrual Cycle', 'comparison', 'Placental mammals show cyclical changes during the reproductive phase.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cycle","Source organisms"],"rows":[["Oestrus cycle","Non-primate mammals such as cows, sheep, rat, deer, dog, tiger etc."],["Menstrual cycle","Primates such as monkeys, apes and humans"]]}'::jsonb, null, null, '{"recall_question":"Which cycle occurs in primates?","reveal_answer":"Menstrual cycle.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 91, 12, true),
  ('neet-biology-reproduction-in-organisms-sexual-reproduction-events', 'neet-biology-reproduction-in-organisms', 'Sexual Reproduction Events', 'sequence', 'Sexual reproduction is divided into pre-fertilisation, fertilisation and post-fertilisation events.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Event","Source-backed recall"],"rows":[["Pre-fertilisation","Events before gamete fusion; includes gametogenesis and gamete transfer"],["Fertilisation or syngamy","Fusion of gametes to form a diploid zygote"],["Post-fertilisation","Events after zygote formation, including embryogenesis"]]}'::jsonb, '{"type":"bio-reproduction-events"}'::jsonb, null, '{"recall_question":"Name the two pre-fertilisation events.","reveal_answer":"Gametogenesis and gamete transfer.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 91, 13, true),
  ('neet-biology-reproduction-in-organisms-gametes-and-sexuality', 'neet-biology-reproduction-in-organisms', 'Gametes and Sexuality', 'classification', 'Gametes may be similar or distinct, and organisms may be bisexual or unisexual.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Term","Source-backed recall","Examples"],"rows":[["Homogametes or isogametes","Similar gametes that cannot be categorized as male or female","Some algae such as Cladophora"],["Heterogametes","Distinct male and female gametes","Fucus, humans"],["Bisexual plant","Male and female reproductive structures in one individual","Hibiscus, Pisum"],["Monoecious plant","Male and female flowers on same plant","Cucurbits, coconuts, Chara"],["Dioecious plant","Male and female flowers on different plants","Papaya, date palm, Marchantia"]]}'::jsonb, null, null, '{"recall_question":"What are similar gametes called?","reveal_answer":"Homogametes or isogametes.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 91, 14, true),
  ('neet-biology-reproduction-in-organisms-chromosome-numbers', 'neet-biology-reproduction-in-organisms', 'Diploid and Haploid Numbers', 'fact', 'The source lists chromosome numbers in meiocytes and gametes.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Organism","Meiocyte 2n","Gamete n"],"rows":[["Human being","46","23"],["Housefly","12","6"],["Rat","42","21"],["Dog","78","39"],["Cat","38","19"],["Fruit fly","8","4"],["Ophioglossum","1260","630"],["Apple","34","17"],["Rice","24","12"],["Maize","20","10"],["Potato","48","24"],["Onion","16","8"]]}'::jsonb, null, null, '{"recall_question":"What is the gamete chromosome number of Ophioglossum in the source?","reveal_answer":"630.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 92, 15, true),
  ('neet-biology-reproduction-in-organisms-gamete-transfer', 'neet-biology-reproduction-in-organisms', 'Gamete Transfer', 'process', 'Male gametes generally need a medium to move towards the female gamete.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Group/case","Source-backed transfer detail"],"rows":[["Simple plants","Water is the medium; many male gametes are produced"],["Seed plants","Pollen grains carry male gametes; ovule carries egg"],["Peas","Anther and stigma are close, enabling easy pollen transfer"],["Cross-pollinating plants","Pollination transfers pollen to stigma; pollen tube carries male gametes to ovule"]]}'::jsonb, null, null, '{"recall_question":"What carries male gametes in seed plants?","reveal_answer":"Pollen grains.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 92, 16, true),
  ('neet-biology-reproduction-in-organisms-external-vs-internal-fertilisation', 'neet-biology-reproduction-in-organisms', 'External vs Internal Fertilisation', 'comparison', 'Fertilisation may occur outside or inside the organism.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","External fertilisation","Internal fertilisation"],"rows":[["Site","Outside the body in external medium, usually water","Inside the body of the organism"],["Examples","Many algae, bony fishes and amphibians","Terrestrial organisms, reptiles, birds, mammals, bryophytes, pteridophytes, gymnosperms, angiosperms"],["Gamete output","Large number of gametes released into surrounding medium","Many sperms are produced but the number of eggs is very low"],["Protection","Offspring are vulnerable to predators","Better protection in the organism"]]}'::jsonb, '{"type":"bio-fertilisation-types"}'::jsonb, null, '{"recall_question":"Which fertilisation type usually occurs in water outside the body?","reveal_answer":"External fertilisation.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 92, 17, true),
  ('neet-biology-reproduction-in-organisms-parthenogenesis', 'neet-biology-reproduction-in-organisms', 'Parthenogenesis', 'fact', 'The source notes that female gametes may develop into new organisms without fertilisation.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Term","Examples listed"],"rows":[["Parthenogenesis","Rotifers, honeybees, some lizards and birds such as turkey"]]}'::jsonb, null, null, '{"recall_question":"Name one source example of parthenogenesis.","reveal_answer":"Honeybee.","key_points":["Other listed examples include rotifers, some lizards and turkey."],"examples":[],"neet_traps":[]}'::jsonb, 4, 92, 18, true),
  ('neet-biology-reproduction-in-organisms-zygote-and-embryogenesis', 'neet-biology-reproduction-in-organisms', 'Zygote and Embryogenesis', 'process', 'The zygote is the vital link between organisms of one generation and the next.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed recall"],"rows":[["Zygote","Diploid cell formed by syngamy"],["Haplontic life cycle","Zygote divides by meiosis to form haploid spores"],["Embryogenesis","Development of embryo from zygote"],["Cell division","Increases number of cells"],["Cell differentiation","Forms specialized tissues and organs"]]}'::jsonb, null, null, '{"recall_question":"What two processes occur during embryogenesis?","reveal_answer":"Cell division and cell differentiation.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 92, 19, true),
  ('neet-biology-reproduction-in-organisms-oviparous-vs-viviparous', 'neet-biology-reproduction-in-organisms', 'Oviparous vs Viviparous', 'comparison', 'Embryonic development after fertilisation differs in oviparous and viviparous animals.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Oviparous","Viviparous"],"rows":[["Development","Fertilized or unfertilized eggs are laid","Zygote develops into a young one inside the female body"],["Examples/detail","Reptiles and birds lay fertilized eggs with a hard calcareous shell","Most mammals"],["Survival","Eggs hatch after incubation","Young ones have better care and protection, so chances of survival are greater"]]}'::jsonb, null, null, '{"recall_question":"Which condition gives better care and protection in the source?","reveal_answer":"Viviparous condition.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 92, 20, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-flower-reproductive-parts', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Flower Reproductive Parts', 'classification', 'Flowers are the sites of sexual reproduction in angiosperms.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Part","Source-backed recall"],"rows":[["Androecium","Whorl of stamens; male reproductive part"],["Gynoecium","Female reproductive part; one or more pistils"],["Stamen","Filament plus anther"],["Pistil","Stigma, style and ovary"]]}'::jsonb, null, null, '{"recall_question":"What are the two main reproductive parts of a flower?","reveal_answer":"Androecium and gynoecium.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 93, 1, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-anther-structure', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Anther Structure', 'diagram', 'A typical angiosperm anther is bilobed, dithecous and tetragonal.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed recall"],"rows":[["Anther","Terminal, bilobed structure"],["Dithecous","Each anther lobe has two thecae"],["Microsporangia","Four microsporangia, two in each lobe"],["Pollen sacs","Microsporangia develop into pollen sacs packed with pollen grains"]]}'::jsonb, '{"type":"bio-anther-microsporangium"}'::jsonb, null, '{"recall_question":"How many microsporangia are present in a typical anther?","reveal_answer":"Four.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 93, 2, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-microsporangium-wall', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Microsporangium Wall Layers', 'classification', 'The microsporangium is surrounded by four wall layers.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Layer","Source-backed role"],"rows":[["Epidermis","Protection"],["Endothecium","Protection and dehiscence"],["Middle layers","Protection and dehiscence"],["Tapetum","Nourishes developing pollen grains; dense cytoplasm and generally more than one nucleus"]]}'::jsonb, null, null, '{"recall_question":"Which anther wall layer nourishes developing pollen grains?","reveal_answer":"Tapetum.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 93, 3, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-microsporogenesis', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Microsporogenesis', 'sequence', 'Microsporogenesis forms microspores from pollen mother cells by meiosis.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Source-backed event"],"rows":[["1","Sporogenous tissue occupies centre of young anther"],["2","Each sporogenous cell becomes a microspore mother cell or pollen mother cell"],["3","PMC undergoes meiosis"],["4","Microspore tetrads are formed"],["5","Microspores dissociate and develop into pollen grains"]]}'::jsonb, null, null, '{"recall_question":"What is microsporogenesis?","reveal_answer":"Formation of microspores from pollen mother cell by meiosis.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 93, 4, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-pollen-grain', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Pollen Grain', 'diagram', 'Pollen grain is the male gametophyte.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Part","Source-backed recall"],"rows":[["Size","Generally spherical, about 25-50 micrometre in diameter"],["Exine","Hard outer layer made of sporopollenin"],["Germ pore","Aperture where sporopollenin is absent"],["Intine","Thin continuous layer made of cellulose and pectin"],["Vegetative cell","Bigger cell with abundant food reserve and large irregular nucleus"],["Generative cell","Small spindle-shaped cell floating in vegetative cytoplasm"]]}'::jsonb, '{"type":"bio-pollen-grain"}'::jsonb, null, '{"recall_question":"Which pollen wall layer contains sporopollenin?","reveal_answer":"Exine.","key_points":[],"examples":[],"neet_traps":["Germ pores are apertures where sporopollenin is absent."]}'::jsonb, 5, 94, 5, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-two-celled-vs-three-celled-pollen', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Two-Celled vs Three-Celled Pollen', 'neet_trap', 'Pollen shedding stage varies among angiosperms.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Stage","Source-backed detail"],"rows":[["2-celled pollen","More than 60% of angiosperms shed pollen grains at this stage"],["3-celled pollen","In remaining species, generative cell divides mitotically to form two male gametes before pollen grains are shed"]]}'::jsonb, null, null, '{"recall_question":"At which stage are pollen grains shed in more than 60% of angiosperms?","reveal_answer":"2-celled stage.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 94, 6, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-pollen-viability-and-use', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Pollen Viability and Uses', 'fact', 'Pollen viability depends on temperature and humidity and varies across plants.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Cereals such as rice and wheat","Pollen viability is 30 minutes"],["Some Leguminoseae, Rosaceae and Solanaceae","Pollen viability is for months"],["Liquid nitrogen","Pollen grains can be stored for years in liquid nitrogen at -196°C"],["Parthenium or carrot grass","Pollen can cause chronic respiratory disorders such as asthma and bronchitis"]]}'::jsonb, null, null, '{"recall_question":"How long is pollen viability in cereals such as rice and wheat?","reveal_answer":"30 minutes.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 94, 7, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-gynoecium-and-pistil', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Gynoecium and Pistil', 'classification', 'A pistil has stigma, style and ovary.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Structure","Source-backed recall"],"rows":[["Monocarpellary","Gynoecium with one pistil"],["Multicarpellary syncarpous","More than one pistil fused"],["Multicarpellary apocarpous","More than one pistil free"],["Stigma","Landing platform for pollen grains"],["Style","Slender part below stigma"],["Ovary","Basal bulged part with ovarian cavity or locule"],["Placenta","Tissue inside ovary where ovules arise"]]}'::jsonb, null, null, '{"recall_question":"What is the landing platform for pollen grains?","reveal_answer":"Stigma.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 94, 8, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-ovule-structure', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Ovule Structure', 'diagram', 'The ovule is attached to the placenta by a funicle.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Part","Source-backed recall"],"rows":[["Funicle","Stalk by which ovule is attached to placenta"],["Hilum","Junction between ovule and funicle"],["Integuments","Protective layers that encircle ovule except at micropyle"],["Micropyle","Opening at the ovule tip"],["Chalaza","Basal part opposite micropyle"],["Nucellus","Mass of cells with abundant reserve food"],["Embryo sac","Female gametophyte located in nucellus"]]}'::jsonb, '{"type":"bio-ovule"}'::jsonb, null, '{"recall_question":"Which ovule part lies opposite the micropyle?","reveal_answer":"Chalaza.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 94, 9, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-megasporogenesis', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Megasporogenesis', 'sequence', 'Megasporogenesis forms megaspores from the megaspore mother cell.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Source-backed event"],"rows":[["1","Single megaspore mother cell differentiates in the micropylar region of nucellus"],["2","MMC undergoes meiosis"],["3","Four megaspores are formed"],["4","Only one megaspore is functional in the majority of flowering plants"],["5","Other three megaspores degenerate"]]}'::jsonb, null, null, '{"recall_question":"In most flowering plants, how many megaspores remain functional?","reveal_answer":"One.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 94, 10, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-embryo-sac-formation', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Embryo Sac Formation', 'sequence', 'The mature embryo sac is 8-nucleate and 7-celled.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Stage/part","Source-backed recall"],"rows":[["Functional megaspore","Develops into female gametophyte by monosporic development"],["Nuclear divisions","2-nucleate, then 4-nucleate, then 8-nucleate stages"],["Cellular organization","6 nuclei enclosed by cell walls, 2 polar nuclei in central cell"],["Egg apparatus","Two synergids and one egg at micropylar end"],["Filiform apparatus","Present at micropylar tip of synergids; guides pollen tubes"],["Antipodals","Three cells at chalazal end"]]}'::jsonb, '{"type":"bio-embryo-sac"}'::jsonb, null, '{"recall_question":"What is the mature embryo sac organization?","reveal_answer":"8-nucleate and 7-celled.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 94, 11, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-autogamy-geitonogamy-xenogamy', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Autogamy vs Geitonogamy vs Xenogamy', 'comparison', 'Pollination is transfer of pollen from anther to stigma.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Type","Source-backed definition","Genetic note/examples"],"rows":[["Autogamy","Pollen from anther to stigma of the same flower","Viola, Oxalis and Commelina show cleistogamous flowers"],["Geitonogamy","Pollen from anther to stigma of another flower on the same plant","Functionally cross-pollination but genetically similar to autogamy"],["Xenogamy","Pollen from anther to stigma of a different plant","Brings genetically different pollen"]]}'::jsonb, null, null, '{"recall_question":"Which pollination is genetically similar to autogamy but functionally cross-pollination?","reveal_answer":"Geitonogamy.","key_points":[],"examples":[],"neet_traps":["Xenogamy involves a different plant."]}'::jsonb, 5, 95, 12, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-wind-water-animal-pollination', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Pollination Agents', 'comparison', 'The source contrasts wind, water and animal pollination.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Agent","Source-backed adaptations/examples"],"rows":[["Wind","Enormous pollen, light non-sticky pollen, exposed stamens, large feathery stigma; common in grasses"],["Water","Rare, about 30 genera mostly monocots; Vallisneria, Hydrilla and Zostera"],["Animals","Bees, butterflies, flies, beetles, wasps, ants, moths, sunbirds, humming birds, bats, lemurs, rodents, reptiles"]]}'::jsonb, null, null, '{"recall_question":"Which abiotic pollination is common in grasses?","reveal_answer":"Wind pollination.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 95, 13, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-pollination-special-cases', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Pollination Special Cases', 'examples', 'The source names several high-yield examples and exceptions in pollination.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Cleistogamous flowers","Do not open; produce assured seed-set even without pollinators"],["Water hyacinth and water lily","Aquatic plants whose flowers emerge above water and are pollinated by insects or wind"],["Amorphophallus","Tallest flower of about 6 feet"],["Yucca and moth","Mutualistic relationship; both cannot complete life cycles without each other"],["Nectar robbers","Animals that consume nectar without bringing pollination"]]}'::jsonb, null, null, '{"recall_question":"Which source example has mutualism with moth?","reveal_answer":"Yucca.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 95, 14, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-outbreeding-devices', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Outbreeding Devices', 'classification', 'Outbreeding devices discourage self-pollination and encourage cross-pollination.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Device","Source-backed recall"],"rows":[["Asynchrony","Pollen release and stigma receptivity are not synchronized"],["Spatial separation","Anther and stigma are placed in different positions"],["Self-incompatibility","Genetic mechanism preventing self-pollen germination or pollen tube growth"],["Unisexuality","Monoecious castor and maize prevent autogamy; dioecious papaya prevents autogamy and geitonogamy"]]}'::jsonb, null, null, '{"recall_question":"Which outbreeding device prevents self pollen germination or pollen tube growth?","reveal_answer":"Self-incompatibility.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 96, 15, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-artificial-hybridisation', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Artificial Hybridisation', 'sequence', 'Artificial hybridisation uses only desired pollen grains for crop improvement.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Source-backed event"],"rows":[["1","Emasculation: remove anthers from bisexual flower bud before anther dehiscence"],["2","Bag the emasculated flower with butter paper"],["3","Dust desired pollen on receptive stigma"],["4","Rebag the flower and allow fruit development"],["Unisexual flowers","Emasculation is not needed; female flower buds are bagged before opening"]]}'::jsonb, null, null, '{"recall_question":"What is emasculation?","reveal_answer":"Removal of anthers from a bisexual flower bud before anther dehiscence.","key_points":[],"examples":[],"neet_traps":["Emasculation is not needed in unisexual flowers."]}'::jsonb, 5, 96, 16, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-pollen-pistil-interaction', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Pollen-Pistil Interaction', 'process', 'The pistil recognizes compatible and incompatible pollen by chemical components.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Source-backed event"],"rows":[["1","Pollen lands on stigma"],["2","Pistil accepts compatible pollen and rejects incompatible pollen"],["3","Pollen germinates through germ pore"],["4","Pollen tube grows through stigma and style to ovary"],["5","Pollen tube enters ovule through micropyle and then one synergid through filiform apparatus"]]}'::jsonb, null, null, '{"recall_question":"Which structure guides pollen tube entry into a synergid?","reveal_answer":"Filiform apparatus.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 96, 17, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-double-fertilisation', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Double Fertilisation', 'process', 'Double fertilisation is unique to flowering plants.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Fusion","Source-backed result"],"rows":[["Syngamy","One male gamete fuses with egg nucleus to form diploid zygote"],["Triple fusion","Other male gamete fuses with two polar nuclei to form triploid primary endosperm nucleus"],["Double fertilisation","Syngamy plus triple fusion"],["After triple fusion","Central cell becomes primary endosperm cell and develops into endosperm"]]}'::jsonb, '{"type":"bio-double-fertilisation"}'::jsonb, null, '{"recall_question":"What two fusion events together constitute double fertilisation?","reveal_answer":"Syngamy and triple fusion.","key_points":[],"examples":[],"neet_traps":["Triple fusion forms triploid PEN, not zygote."]}'::jsonb, 5, 96, 18, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-endosperm', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Endosperm', 'classification', 'Endosperm develops from the primary endosperm cell and stores reserve food for the embryo.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Type/detail","Source-backed recall"],"rows":[["Free-nuclear endosperm","PEN undergoes successive nuclear divisions to give free nuclei"],["Cellular endosperm","Cell wall formation follows free nuclear divisions"],["Tender coconut water","Free-nuclear endosperm"],["White kernel of coconut","Cellular endosperm"]]}'::jsonb, null, null, '{"recall_question":"What is tender coconut water in the source?","reveal_answer":"Free-nuclear endosperm.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 97, 19, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-embryo-development', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Embryo Development', 'sequence', 'Embryo develops at the micropylar end where the zygote is situated.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Stage/part","Source-backed recall"],"rows":[["Sequence","Zygote -> pro-embryo -> globular -> heart-shaped -> mature embryo"],["Dicot embryo","Embryonal axis and two cotyledons"],["Epicotyl","Portion above cotyledons; terminates in plumule"],["Hypocotyl","Portion below cotyledons; terminates in radicle"],["Monocot embryo","One cotyledon; grass cotyledon is scutellum"],["Coleorrhiza and coleoptile","Radicle/root cap enclosed by coleorrhiza; shoot apex and leaf primordia enclosed by coleoptile"]]}'::jsonb, null, null, '{"recall_question":"What is the cotyledon of grasses called?","reveal_answer":"Scutellum.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 97, 20, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-seed-types', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Albuminous vs Non-Albuminous Seeds', 'comparison', 'Mature seeds may or may not retain endosperm.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Seed type","Source-backed recall","Examples"],"rows":[["Non-albuminous or ex-albuminous","No residual endosperm because it is completely consumed during embryo development","Pea, groundnut, beans"],["Albuminous","Retain a part of endosperm","Wheat, maize, barley, castor, coconut"],["Perisperm","Remnant nucellus","Black pepper, beet etc."]]}'::jsonb, null, null, '{"recall_question":"Which seed type retains part of the endosperm?","reveal_answer":"Albuminous seed.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 97, 21, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-seed-viability', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Seed Viability', 'fact', 'Seed viability varies from months to thousands of years in source examples.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Example","Source-backed value"],"rows":[["Mature seed moisture","10-15% moisture by mass"],["Lupinus arcticus","Estimated 10,000 years of dormancy; germinated and flowered"],["Phoenix dactylifera","2000-year-old viable date palm seed from King Herod''s palace near Dead Sea"]]}'::jsonb, null, null, '{"recall_question":"What moisture range is stated for mature dry seeds?","reveal_answer":"10-15% moisture by mass.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 97, 22, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-true-false-parthenocarpic-fruits', 'neet-biology-sexual-reproduction-in-flowering-plants', 'True, False and Parthenocarpic Fruits', 'classification', 'Fruit develops as ovary and ovules transform after fertilisation, with source-backed exceptions.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Fruit type","Source-backed recall","Examples"],"rows":[["True fruit","Fruit formed only from ovary","Most plants"],["False fruit","Thalamus also contributes to fruit formation","Apple, strawberry, cashew"],["Parthenocarpic fruit","Fruit formed without fertilisation","Banana"]]}'::jsonb, null, null, '{"recall_question":"Which listed fruit is parthenocarpic?","reveal_answer":"Banana.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 98, 23, true),
  ('neet-biology-sexual-reproduction-in-flowering-plants-apomixis-polyembryony', 'neet-biology-sexual-reproduction-in-flowering-plants', 'Apomixis and Polyembryony', 'comparison', 'Apomixis is asexual seed formation that mimics sexual reproduction.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Term","Source-backed recall","Examples"],"rows":[["Apomixis","Seed formation without fertilisation","Asteraceae and grasses"],["Diploid egg route","Diploid egg cell forms embryo without reduction division and fertilisation","Source mechanism"],["Nucellar embryo route","Nucellar cells around embryo sac divide, protrude into embryo sac and develop into embryos","Citrus and Mango varieties"],["Polyembryony","Occurrence of more than one embryo in a seed","Seen when more embryos form in one ovule"]]}'::jsonb, null, null, '{"recall_question":"What is polyembryony?","reveal_answer":"Occurrence of more than one embryo in a seed.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 98, 24, true),
