  ('neet-biology-human-reproduction-male-duct-route', 'neet-biology-human-reproduction', 'Male Duct Route', 'sequence', 'Sperm pass from seminiferous tubules to the urethral meatus through accessory ducts.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Order","Route"],"rows":[["1","Seminiferous tubules"],["2","Rete testis"],["3","Vasa efferentia"],["4","Epididymis"],["5","Vas deferens"],["6","Ejaculatory duct"],["7","Urethra"],["8","Urethral meatus"]]}'::jsonb, null, null, '{"recall_question":"Which duct comes after rete testis in the male route?","reveal_answer":"Vasa efferentia.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 99, 3, true),
  ('neet-biology-human-reproduction-sertoli-vs-leydig', 'neet-biology-human-reproduction', 'Sertoli vs Leydig Cells', 'comparison', 'Sertoli cells and Leydig cells support different parts of male reproduction.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cell","Location","Source-backed function"],"rows":[["Sertoli cells","Seminiferous tubules","Support and nourish spermatogonia/sperms; secrete factors for spermiogenesis under FSH"],["Leydig cells","Interstitial spaces outside seminiferous tubules","Secrete androgens under LH stimulation"]]}'::jsonb, null, null, '{"recall_question":"Which cells secrete androgens?","reveal_answer":"Leydig cells.","key_points":[],"examples":[],"neet_traps":["Sertoli cells nourish and support developing sperms."]}'::jsonb, 5, 99, 4, true),
